                  "<?php\n\nnamespace App\\Http\\Controllers;\n\nuse Illuminate\\Http\\Request;\nuse Illuminate\\Routing\\Controller;\n\nabstract class BaseController extends Controller\n{\n    protected $service;\n\n    public function __construct($service)\n    {\n        $this->service = $service;\n    }\n\n    // CRUD\n\n    public function index()\n    {\n        $items = $this->service->getAll();\n        return response()->json($items);\n    }\n\n    public function show($id)\n    {\n        $item = $this->service->findById($id);\n        return $item ? response()->json($item) : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    public function store(Request $request)\n    {\n        $item = $this->service->create($request->all());\n        return response()->json($item, 201);\n    }\n\n    public function update(Request $request, $id)\n    {\n        $updated = $this->service->update($id, $request->all());\n        return $updated ? response()->json(['message' => 'Resource updated']) : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    public function destroy($id)\n    {\n        $deleted = $this->service->delete($id);\n        return $deleted ? response()->json(['message' => 'Resource deleted']) : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    // Query and Search\n\n    public function findByAttributes(Request $request)\n    {\n        $attributes = $request->all();\n        $item = $this->service->findByAttributes($attributes);\n        return $item ? response()->json($item) : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    public function paginate(Request $request)\n    {\n        $perPage = $request->input('per_page', 15);\n        $items = $this->service->paginate($perPage);\n        return response()->json($items);\n    }\n\n    public function search(Request $request)\n    {\n        $query = $request->input('query');\n        $fields = $request->input('fields', []);\n        $perPage = $request->input('per_page', 15);\n        $results = $this->service->search($query, $fields, $perPage);\n        return response()->json($results);\n    }\n\n    public function count(Request $request)\n    {\n        $criteria = $request->all();\n        $count = $this->service->count($criteria);\n        return response()->json(['count' => $count]);\n    }\n\n    public function exists(Request $request)\n    {\n        $criteria = $request->all();\n        $exists = $this->service->exists($criteria);\n        return response()->json(['exists' => $exists]);\n    }\n\n    // Soft Deletes and Restoration\n\n    public function softDelete($id)\n    {\n        $softDeleted = $this->service->softDelete($id);\n        return $softDeleted\n        ? response()->json(['message' => 'Resource soft-deleted'])\n        : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    public function restore($id)\n    {\n        $restored = $this->service->restore($id);\n        return $restored\n        ? response()->json(['message' => 'Resource restored'])\n        : response()->json(['message' => 'Resource not found'], 404);\n    }\n\n    public function withTrashed()\n    {\n        $items = $this->service->withTrashed();\n        return response()->json($items);\n    }\n\n    public function onlyTrashed()\n    {\n        $items = $this->service->onlyTrashed();\n        return response()->json($items);\n    }\n\n    public function withoutTrashed()\n    {\n        $items = $this->service->withoutTrashed();\n        return response()->json($items);\n    }\n\n    // Bulk Operations\n\n    public function batchUpdate(Request $request)\n    {\n        $criteria = $request->input('criteria', []);\n        $data = $request->input('data', []);\n        $updated = $this->service->batchUpdate($criteria, $data);\n        return response()->json(['updated' => $updated]);\n    }\n\n    public function updateOrCreate(Request $request)\n    {\n        $attributes = $request->input('attributes', []);\n        $values = $request->input('values', []);\n        $item = $this->service->updateOrCreate($attributes, $values);\n        return response()->json($item);\n    }\n\n    // Retrieval and Sorting\n\n    public function findOrFail($id)\n    {\n        $item = $this->service->findOrFail($id);\n        return response()->json($item);\n    }\n\n    public function findMany(Request $request)\n    {\n        $ids = $request->input('ids', []);\n        $items = $this->service->findMany($ids);\n        return response()->json($items);\n    }\n\n    public function random(Request $request)\n    {\n        $count = $request->input('count', 1);\n        $items = $this->service->random($count);\n        return response()->json($items);\n    }\n\n    public function latest(Request $request)\n    {\n        $column = $request->input('column', 'created_at');\n        $item = $this->service->latest($column);\n        return response()->json($item);\n    }\n\n    public function oldest(Request $request)\n    {\n        $column = $request->input('column', 'created_at');\n        $item = $this->service->oldest($column);\n        return response()->json($item);\n    }\n\n    public function orderBy(Request $request)\n    {\n        $column = $request->input('column');\n        $direction = $request->input('direction', 'asc');\n        $items = $this->service->orderBy($column, $direction);\n        return response()->json($items);\n    }\n\n    public function groupBy(Request $request)\n    {\n        $column = $request->input('column');\n        $items = $this->service->groupBy($column);\n        return response()->json($items);\n    }\n\n    // Advanced Operations\n\n    public function getWithRelations(Request $request)\n    {\n        $relations = $request->input('relations', []);\n        $items = $this->service->getWithRelations($relations);\n        return response()->json($items);\n    }\n\n    public function pluck(Request $request)\n    {\n        $column = $request->input('column');\n        $key = $request->input('key', null);\n        $values = $this->service->pluck($column, $key);\n        return response()->json($values);\n    }\n\n    public function firstOrCreate(Request $request)\n    {\n        $attributes = $request->input('attributes', []);\n        $values = $request->input('values', []);\n        $item = $this->service->firstOrCreate($attributes, $values);\n        return response()->json($item);\n    }\n\n    public function firstOrNew(Request $request)\n    {\n        $attributes = $request->input('attributes', []);\n        $values = $request->input('values', []);\n        $item = $this->service->firstOrNew($attributes, $values);\n        return response()->json($item);\n    }\n\n    public function chunk(Request $request)\n    {\n        $size = $request->input('size', 100);\n        $callback = function ($items) {\n        return response()->json($items);\n        };\n        $this->service->chunk($size, $callback);\n    }\n\n    public function each()\n    {\n        $callback = function ($item) {\n        return response()->json($item);\n        };\n        $this->service->each($callback);\n    }\n\n    public function whereIn(Request $request)\n    {\n        $column = $request->input('column');\n        $values = $request->input('values', []);\n        $items = $this->service->whereIn($column, $values);\n        return response()->json($items);\n    }\n\n    public function whereNotIn(Request $request)\n    {\n        $column = $request->input('column');\n        $values = $request->input('values', []);\n        $items = $this->service->whereNotIn($column, $values);\n        return response()->json($items);\n    }\n\n    public function whereBetween(Request $request)\n    {\n        $column = $request->input('column');\n        $range = $request->input('range', []);\n        $items = $this->service->whereBetween($column, $range);\n        return response()->json($items);\n    }\n}\n",
